INSERT INTO rpg.phb_creature_template_action (
  template_slug, name, action_bucket, attack_bonus, damage_expression, description, sort_order
) VALUES
  ('abominable-yeti', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The yeti can use its Chilling Gaze and makes two attacks, using Claw or Ice Throw in any combination.', 1),
  ('abominable-yeti', 'Claw', 'action'::rpg.actor_action_bucket, 11, '14', 'Melee Attack Roll: +11, reach 5 ft. Hit: 14 (2d6 + 7) Slashing damage plus 7 (2d6) Cold damage.', 2),
  ('abominable-yeti', 'Ice Throw', 'action'::rpg.actor_action_bucket, 11, '12', 'Ranged Attack Roll: +11, range 60/240 ft. Hit: 12 (2d4 + 7) Bludgeoning damage plus 7 (2d6) Cold damage.', 3),
  ('abominable-yeti', 'Chilling Gaze', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 18, one creature the yeti can see within 30 feet. Failure: 21 (6d6) Cold damage, and the target has the Paralyzed condition until the start of the yeti’s next turn unless the target has Immunity to Cold damage. Success: The target is immune to this yeti’s Chilling Gaze for 1 hour.', 4),
  ('abominable-yeti', 'Cold Breath (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 18, each creature in a 30-foot Cone. Failure: 45 (10d8) Cold damage. Success: Half damage.', 5),
  ('archpriest', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The archpriest makes three Radiant Burst attacks.', 1),
  ('archpriest', 'Radiant Burst', 'action'::rpg.actor_action_bucket, 9, '27', 'Melee or Ranged Attack Roll: +9, reach 5 ft. or range 60 ft. Hit: 27 (4d10 + 5) Radiant damage.', 2),
  ('archpriest', 'Holy Word (Recharge 4–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 17, each enemy in a 20-foot Emanation originating from the archpriest. Failure: 21 (6d6) Radiant damage, and the target has the Stunned condition until the end of the archpriest’s next turn. Success: Half damage only.', 3),
  ('archpriest', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The archpriest casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 17):', 4),
  ('archpriest', 'Divine Aid (3/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The priest casts Bless, Dispel Magic, Healing Word, or Lesser Restoration, using the same spellcasting ability as Spellcasting.', 5),
  ('arquimago', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The archmage makes four Arcane Burst attacks.', 1),
  ('arquimago', 'Arcane Burst', 'action'::rpg.actor_action_bucket, 9, '27', 'Melee or Ranged Attack Roll: +9, reach 5 ft. or range 150 ft. Hit: 27 (4d10 + 5) Force damage.', 2),
  ('arquimago', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The archmage casts one of the following spells, using Intelligence as the spellcasting ability (spell save DC 17):', 3),
  ('arquimago', 'Misty Step (3/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The mage casts Misty Step, using the same spellcasting ability as Spellcasting.', 4),
  ('arquimago', 'Protective Magic (3/Day)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The archmage casts Counterspell or Shield in response to the spell’s trigger, using the same spellcasting ability as Spellcasting.', 5),
  ('arvorente', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The treant makes two Slam attacks.', 1),
  ('arvorente', 'Slam', 'action'::rpg.actor_action_bucket, 10, '16', 'Melee Attack Roll: +10, reach 5 ft. Hit: 16 (3d6 + 6) Bludgeoning damage.', 2),
  ('arvorente', 'Hail of Bark', 'action'::rpg.actor_action_bucket, 10, '28', 'Ranged Attack Roll: +10, range 180 ft. Hit: 28 (4d10 + 6) Piercing damage.', 3),
  ('arvorente', 'Animate Trees (1/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The treant magically animates up to two trees it can see within 60 feet of itself. Each tree uses the Treant stat block, except it has Intelligence and Charisma scores of 1, it can’t speak, and it lacks this action. The tree takes its turn immediately after the treant on the same Initiative count, and it obeys the treant. A tree remains animate for 1 day or until it dies, the treant dies, or it is more than 120 feet from the treant. The tree then takes root if possible.', 4),
  ('batedor', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The scout makes two attacks, using Shortsword and Longbow in any combination.', 1),
  ('batedor', 'Shortsword', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage.', 2),
  ('batedor', 'Longbow', 'action'::rpg.actor_action_bucket, 4, '6', 'Ranged Attack Roll: +4, range 150/600 ft. Hit: 6 (1d8 + 2) Piercing damage.', 3),
  ('batedor-capitao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The scout makes two attacks, using Shortsword or Longbow in any combination.', 1),
  ('batedor-capitao', 'Shortsword', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage, plus 10 (3d6) Piercing damage if the attack was made with Advantage.', 2),
  ('batedor-capitao', 'Longbow', 'action'::rpg.actor_action_bucket, 5, '7', 'Ranged Attack Roll: +5, range 150/600 ft. Hit: 7 (1d8 + 3) Piercing damage, plus 10 (3d6) Piercing damage if the attack was made with Advantage.', 3),
  ('batedor-capitao', 'Aim', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The scout has Advantage on the next attack roll it makes during the current turn.', 4),
  ('batedor-capitao', 'Uncanny Dodge', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The scout is hit by an attack roll. Response: The scout halves the damage (round down) it takes from that attack.', 5),
  ('bruxa-do-mar', 'Claw', 'action'::rpg.actor_action_bucket, 5, '10', 'Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage.', 1),
  ('bruxa-do-mar', 'Death Glare (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 11, one Frightened creature the hag can see within 30 feet. Failure: If the target has 20 Hit Points or fewer, it drops to 0 Hit Points. Otherwise, the target takes 13 (3d8) Psychic damage.', 2),
  ('bruxa-do-mar', 'Illusory Appearance', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hag casts Disguise Self, using Constitution as the spellcasting ability (spell save DC 13). The spell’s duration is 24 hours.', 3),
  ('demonio-das-sombras', 'Umbral Claw', 'action'::rpg.actor_action_bucket, 5, '16', 'Melee Attack Roll: +5, reach 5 ft. Hit: 16 (3d8 + 3) Psychic damage.', 1),
  ('demonio-das-sombras', 'Shadow Stealth', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'While in Dim Light or Darkness, the demon takes the Hide action.', 2),
  ('diabo-espinhudo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil makes two attacks, using Infernal Fork and Tail Spine in any combination.', 1),
  ('diabo-espinhudo', 'Infernal Fork', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage plus 3 (1d6) Fire damage.', 2),
  ('diabo-espinhudo', 'Tail Spine', 'action'::rpg.actor_action_bucket, 4, '4', 'Ranged Attack Roll: +4, range 20/80 ft. Hit: 4 (1d4 + 2) Piercing damage plus 3 (1d6) Fire damage.', 3),
  ('dragao-branco-adulto', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks.', 1),
  ('dragao-branco-adulto', 'Rend', 'action'::rpg.actor_action_bucket, 11, '13', 'Melee Attack Roll: +11, reach 10 ft. Hit: 13 (2d6 + 6) Slashing damage plus 4 (1d8) Cold damage.', 2),
  ('dragao-branco-adulto', 'Cold Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 19, each creature in a 60-foot Cone. Failure: 54 (12d8) Cold damage. Success: Half damage.', 3),
  ('dragao-branco-adulto', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the dragon can expend a use to take one of the following actions. The dragon regains all expended uses at the start of each of its turns.', 4),
  ('dragao-branco-adulto', 'Freezing Burst', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 14, each creature in a 30-foot-radius Sphere centered on a point the dragon can see within 120 feet. Failure: 7 (2d6) Cold damage, and the target’s Speed is 0 until the end of the target’s next turn. Failure or Success: The dragon can’t take this action again until the start of its next turn.', 5),
  ('dragao-branco-adulto', 'Frightful Presence', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon casts Fear, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 14). The dragon can’t take this action again until the start of its next turn.', 6),
  ('dragao-branco-adulto', 'Pounce', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon moves up to half its Speed, and it makes one Rend attack.', 7),
  ('dragao-branco-anciano', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks.', 1),
  ('dragao-branco-anciano', 'Rend', 'action'::rpg.actor_action_bucket, 14, '17', 'Melee Attack Roll: +14, reach 15 ft. Hit: 17 (2d8 + 8) Slashing damage plus 7 (2d6) Cold damage.', 2),
  ('dragao-branco-anciano', 'Cold Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 22, each creature in a 90-foot Cone. Failure: 63 (14d8) Cold damage. Success: Half damage.', 3),
  ('dragao-branco-anciano', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the dragon can expend a use to take one of the following actions. The dragon regains all expended uses at the start of each of its turns.', 4),
  ('dragao-branco-anciano', 'Freezing Burst', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 20, each creature in a 30-foot-radius Sphere centered on a point the dragon can see within 120 feet. Failure: 14 (4d6) Cold damage, and the target’s Speed is 0 until the end of the target’s next turn. Failure or Success: The dragon can’t take this action again until the start of its next turn.', 5),
  ('dragao-branco-anciano', 'Frightful Presence', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon casts Fear, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 18). The dragon can’t take this action again until the start of its next turn.', 6),
  ('dragao-branco-anciano', 'Pounce', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon moves up to half its Speed, and it makes one Rend attack.', 7),
  ('dragao-branco-jovem', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks.', 1),
  ('dragao-branco-jovem', 'Rend', 'action'::rpg.actor_action_bucket, 7, '9', 'Melee Attack Roll: +7, reach 10 ft. Hit: 9 (2d4 + 4) Slashing damage plus 2 (1d4) Cold damage.', 2),
  ('dragao-branco-jovem', 'Cold Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 15, each creature in a 30-foot Cone. Failure: 40 (9d8) Cold damage. Success: Half damage.', 3),
  ('dragao-prateado-adulto', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks. It can replace one attack with a use of (A) Paralyzing Breath or (B) Spellcasting to cast Ice Knife.', 1),
  ('dragao-prateado-adulto', 'Rend', 'action'::rpg.actor_action_bucket, 13, '17', 'Melee Attack Roll: +13, reach 10 ft. Hit: 17 (2d8 + 8) Slashing damage plus 4 (1d8) Cold damage.', 2),
  ('dragao-prateado-adulto', 'Cold Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 20, each creature in a 60-foot Cone. Failure: 54 (12d8) Cold damage. Success: Half damage.', 3),
  ('dragao-prateado-adulto', 'Paralyzing Breath', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 20, each creature in a 60-foot Cone. First Failure: The target has the Incapacitated condition until the end of its next turn, when it repeats the save. Second Failure: The target has the Paralyzed condition, and it repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.', 4),
  ('dragao-prateado-adulto', 'Spellcasting', 'action'::rpg.actor_action_bucket, 11, NULL, 'The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 19, +11 to hit with spell attacks):', 5),
  ('dragao-prateado-adulto', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the dragon can expend a use to take one of the following actions. The dragon regains all expended uses at the start of each of its turns.', 6),
  ('dragao-prateado-adulto', 'Chill', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon uses Spellcasting to cast Hold Monster. The dragon can’t take this action again until the start of its next turn.', 7),
  ('dragao-prateado-adulto', 'Cold Gale', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 19, each creature in a 60-foot-long, 10-foot-wide Line. Failure: 14 (4d6) Cold damage, and the target is pushed up to 30 feet straight away from the dragon. Success: Half damage only. Failure or Success: The dragon can’t take this action again until the start of its next turn.', 8),
  ('dragao-prateado-adulto', 'Pounce', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon moves up to half its Speed, and it makes one Rend attack.', 9),
  ('dragao-prateado-anciano', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks. It can replace one attack with a use of (A) Paralyzing Breath or (B) Spellcasting to cast Ice Knife (level 2 version).', 1),
  ('dragao-prateado-anciano', 'Rend', 'action'::rpg.actor_action_bucket, 17, '19', 'Melee Attack Roll: +17, reach 15 ft. Hit: 19 (2d8 + 10) Slashing damage plus 9 (2d8) Cold damage.', 2),
  ('dragao-prateado-anciano', 'Cold Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 24, each creature in a 90-foot Cone. Failure: 67 (15d8) Cold damage. Success: Half damage.', 3),
  ('dragao-prateado-anciano', 'Paralyzing Breath', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 24, each creature in a 90-foot Cone. First Failure: The target has the Incapacitated condition until the end of its next turn, when it repeats the save. Second Failure: The target has the Paralyzed condition, and it repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.', 4),
  ('dragao-prateado-anciano', 'Spellcasting', 'action'::rpg.actor_action_bucket, 15, NULL, 'The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 23, +15 to hit with spell attacks):', 5),
  ('dragao-prateado-anciano', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the dragon can expend a use to take one of the following actions. The dragon regains all expended uses at the start of each of its turns.', 6),
  ('dragao-prateado-anciano', 'Chill', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon uses Spellcasting to cast Hold Monster. The dragon can’t take this action again until the start of its next turn.', 7),
  ('dragao-prateado-anciano', 'Cold Gale', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 23, each creature in a 60-foot-long, 10-foot-wide Line. Failure: 14 (4d6) Cold damage, and the target is pushed up to 30 feet straight away from the dragon. Success: Half damage only. Failure or Success: The dragon can’t take this action again until the start of its next turn.', 8),
  ('dragao-prateado-anciano', 'Pounce', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon moves up to half its Speed, and it makes one Rend attack.', 9),
  ('dragao-prateado-jovem', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks. It can replace one attack with a use of Paralyzing Breath.', 1),
  ('dragao-prateado-jovem', 'Rend', 'action'::rpg.actor_action_bucket, 10, '15', 'Melee Attack Roll: +10, reach 10 ft. Hit: 15 (2d8 + 6) Slashing damage.', 2),
  ('dragao-prateado-jovem', 'Cold Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 17, each creature in a 30-foot Cone. Failure: 49 (11d8) Cold damage. Success: Half damage.', 3),
  ('dragao-prateado-jovem', 'Paralyzing Breath', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 17, each creature in a 30-foot Cone. First Failure: The target has the Incapacitated condition until the end of its next turn, when it repeats the save. Second Failure: The target has the Paralyzed condition, and it repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.', 4),
  ('dragao-sombra', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks.', 1),
  ('dragao-sombra', 'Rend', 'action'::rpg.actor_action_bucket, 10, '12', 'Melee Attack Roll: +10, reach 10 ft. Hit: 12 (2d6 + 5) Slashing damage plus 3 (1d6) Necrotic damage.', 2),
  ('dragao-sombra', 'Shadow Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 17, each creature in a 60-foot Cone. Failure: 35 (10d6) Necrotic damage. Success: Half damage. Failure or Success: A Humanoid reduced to 0 Hit Points by this damage dies, and a Shadow rises from the corpse. The shadow is under the dragon’s control and shares the dragon’s Initiative count but acts immediately after the dragon.', 3),
  ('dragao-sombra', 'Shadow Stealth', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'While in Dim Light or Darkness, the dragon takes the Hide action.', 4),
  ('dragao-sombra', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the dragon can expend a use to take one of the following actions. The dragon regains all expended uses at the start of each of its turns.', 5),
