  ('dragonete-dragao-prateado', 'Cold Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 13, each creature in a 15-foot Cone. Failure: 18 (4d8) Cold damage. Success: Half damage.', 3),
  ('dragonete-dragao-prateado', 'Paralyzing Breath', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 13, each creature in a 15-foot Cone. First Failure: The target has the Incapacitated condition until the end of its next turn, when it repeats the save. Second Failure: The target has the Paralyzed condition, and it repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.', 4),
