  ('elemental-da-agua', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The elemental makes two Slam attacks.', 1),
  ('elemental-da-agua', 'Slam', 'action'::rpg.actor_action_bucket, 7, '13', 'Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Bludgeoning damage. If the target is a Medium or smaller creature, it has the Prone condition.', 2),
  ('elemental-da-agua', 'Whelm (Recharge 4–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 15, each creature in the elemental’s space. Failure: 22 (4d8 + 4) Bludgeoning damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14). Until the grapple ends, the target has the Restrained condition, is suffocating unless it can breathe water, and takes 9 (2d8) Bludgeoning damage at the start of each of the elemental’s turns. The elemental can grapple one Large creature or up to two Medium or smaller creatures at a time with Whelm. As an action, a creature within 5 feet of the elemental can pull a creature out of it by succeeding on a DC 14 Strength (Athletics) check. Success: Half damage only.', 3),
  ('enxame-de-stirges', 'Swarm of Proboscises', 'action'::rpg.actor_action_bucket, 5, '14', 'Melee Attack Roll: +5, reach 5 ft. Hit: 14 (2d10 + 3) Piercing damage, or 8 (1d10 + 3) Piercing damage if the swarm is Bloodied. If the target is a Medium or smaller creature in the swarm’s space, the target has the Grappled condition (escape DC 13). Until the grapple ends, the target takes 7 (2d6) Necrotic damage at the end of each of its turns.', 1),
  ('esfinge-do-assombro', 'Rend', 'action'::rpg.actor_action_bucket, 5, '5', 'Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Slashing damage plus 7 (2d6) Radiant damage.', 1),
  ('esfinge-do-assombro', 'Burst of Ingenuity (2/Day)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The sphinx or another creature within 30 feet makes an ability check or a saving throw. Response: The sphinx adds 2 to the roll.', 2),
