  ('esfinge-dos-segredos', 'Curse of the Riddle', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Intelligence Saving Throw: DC 15, one creature the sphinx can see within 60 feet. Failure: 21 (6d6) Psychic damage, and the target is cursed with a riddle. The cursed target has Disadvantage on ability checks and attack rolls. In addition, if it takes the Magic action, it must succeed on a DC 15 Intelligence saving throw or that action is wasted. The cursed target can take a Study action to make a DC 15 Intelligence check, solving the riddle and ending the curse on a success. The curse ends early if the sphinx curses another target.', 3),
  ('esfinge-dos-segredos', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The sphinx casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save DC 15):', 4),
