  ('espectro', 'Life Drain', 'action'::rpg.actor_action_bucket, 4, '7', 'Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d6) Necrotic damage. If the target is a creature, its Hit Point maximum decreases by an amount equal to the damage taken.', 1),
