  ('espiao-mestre', 'Hand Crossbow', 'action'::rpg.actor_action_bucket, 9, '12', 'Ranged Attack Roll: +9, range 30/120 ft. Hit: 12 (2d6 + 5) Piercing damage plus 9 (2d8) Poison damage.', 3),
  ('espiao-mestre', 'Smoke Bomb (1/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The spy throws a bomb to a point it can see within 30 feet of itself. Constitution Saving Throw: DC 16, each creature in a 20-foot-radius Sphere centered on that point. Failure: 28 (8d6) Poison damage, and the target has the Blinded condition until the end of the spy’s next turn. Success: Half damage only.', 4),
  ('espiao-mestre', 'Cunning Action', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The spy takes the Dash, Disengage, or Hide action.', 5),
