  ('familiar-de-vampiro', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The familiar makes two Umbral Dagger attacks.', 1),
  ('familiar-de-vampiro', 'Umbral Dagger', 'action'::rpg.actor_action_bucket, 5, '5', 'Melee or Ranged Attack Roll: +5, reach 5 ft. or range 20/60 ft. Hit: 5 (1d4 + 3) Piercing damage plus 7 (3d4) Necrotic damage. If the target is reduced to 0 Hit Points by this attack, the target becomes Stable but has the Poisoned condition for 1 hour. While it has the Poisoned condition, the target has the Paralyzed condition.', 2),
  ('familiar-de-vampiro', 'Deathless Agility', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The familiar takes the Dash or Disengage action.', 3),
  ('ferrugem-monstro', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The rust monster makes one Bite attack and uses Antennae twice.', 1),
