  ('fogo-fatuo', 'Consume Life', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 10, one living creature the wisp can see within 5 feet that has 0 Hit Points. Failure: The target dies, and the wisp regains 10 (3d6) Hit Points.', 2),
  ('fogo-fatuo', 'Vanish', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The wisp and its light have the Invisible condition until the wisp’s Concentration ends on this effect, which ends early immediately after the wisp makes an attack roll or uses Consume Life.', 3),
  ('gigante-da-pedra', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The giant makes two attacks, using Stone Club or Boulder in any combination.', 1),
