  ('mimico', 'Bite', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5 (with Advantage if the target is Grappled by the mimic), reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage—or 12 (2d8 + 3) Piercing damage if the target is Grappled by the mimic—plus 4 (1d8) Acid damage.', 1),
  ('mimico', 'Pseudopod', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Bludgeoning damage plus 4 (1d8) Acid damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 13). Ability checks made to escape this grapple have Disadvantage.', 2),
  ('mimico', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The mimic shape-shifts to resemble a Medium or Small object while retaining its game statistics, or it returns to its true blob form. Any equipment it is wearing or carrying isn’t transformed.', 3),
  ('minotauro-de-baphomet', 'Abyssal Glaive', 'action'::rpg.actor_action_bucket, 6, '10', 'Melee Attack Roll: +6, reach 10 ft. Hit: 10 (1d12 + 4) Slashing damage plus 10 (3d6) Necrotic damage.', 1),
  ('minotauro-de-baphomet', 'Gore (Recharge 5–6)', 'action'::rpg.actor_action_bucket, 6, '18', 'Melee Attack Roll: +6, reach 5 ft. Hit: 18 (4d6 + 4) Piercing damage. If the target is a Large or smaller creature and the minotaur moved 10+ feet straight toward it immediately before the hit, the target takes an extra 10 (3d6) Piercing damage and has the Prone condition.', 2),
  ('modron-duodrone', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The modron makes two Clockwork Blade attacks.', 1),
  ('modron-duodrone', 'Clockwork Blade', 'action'::rpg.actor_action_bucket, 3, '4', 'Melee or Ranged Attack Roll: +3, reach 5 ft. or range 30 ft. Hit: 4 (1d6 + 1) Force damage. Hit or Miss: The blade magically returns to the modron’s hand immediately after a ranged attack.', 2),
  ('modron-monodrone', 'Gear', 'action'::rpg.actor_action_bucket, 4, '6', 'Melee Attack Roll: +4, reach 5 ft. Hit: 6 (1d8 + 2) Force damage.', 1),
  ('modron-monodrone', 'Gear Flinger', 'action'::rpg.actor_action_bucket, 4, '6', 'Ranged Attack Roll: +4, range 120 ft. Hit: 6 (1d8 + 2) Force damage.', 2),
  ('modron-pentadrone', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The modron makes five Slam attacks or five Electrical Discharge attacks.', 1),
  ('modron-pentadrone', 'Slam', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Force damage.', 2),
  ('modron-pentadrone', 'Electrical Discharge', 'action'::rpg.actor_action_bucket, 4, '5', 'Ranged Attack Roll: +4, range 120 ft. Hit: 5 (1d6 + 2) Lightning damage.', 3),
  ('modron-pentadrone', 'Paralysis Gas (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 11, each creature in a 30-foot Cone. Failure: The target has the Paralyzed condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.', 4),
  ('modron-quadrone', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The modron makes four Slam attacks or four Gears Launcher attacks.', 1),
  ('modron-quadrone', 'Slam', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Force damage.', 2),
  ('modron-quadrone', 'Gears Launcher', 'action'::rpg.actor_action_bucket, 4, '4', 'Ranged Attack Roll: +4, range 320 ft. Hit: 4 (1d4 + 2) Force damage.', 3),
  ('modron-tridrone', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The modron makes three Clockwork Spear attacks.', 1),
  ('modron-tridrone', 'Clockwork Spear', 'action'::rpg.actor_action_bucket, 3, '4', 'Melee or Ranged Attack Roll: +3, reach 5 ft. or range 120 ft. Hit: 4 (1d6 + 1) Force damage. Hit or Miss: The spear magically returns to the modron’s hand immediately after a ranged attack.', 2),
  ('monte-cambaleante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The shambling mound makes three Charged Tendril attacks. It can replace one attack with a use of Engulf.', 1),
  ('monte-cambaleante', 'Charged Tendril', 'action'::rpg.actor_action_bucket, 7, '7', 'Melee Attack Roll: +7, reach 10 ft. Hit: 7 (1d6 + 4) Bludgeoning damage plus 5 (2d4) Lightning damage. If the target is a Medium or smaller creature, the shambling mound pulls the target 5 feet straight toward itself.', 2),
  ('monte-cambaleante', 'Engulf', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 15, one Medium or smaller creature within 5 feet. Failure: The target is pulled into the shambling mound’s space and has the Grappled condition (escape DC 14). Until the grapple ends, the target has the Blinded and Restrained conditions, and it takes 10 (3d6) Lightning damage at the start of each of its turns. When the shambling mound moves, the Grappled target moves with it, costing it no extra movement. The shambling mound can have only one creature Grappled by this action at a time.', 3),
  ('mud-mephit', 'Slam', 'action'::rpg.actor_action_bucket, 3, '4', 'Melee Attack Roll: +3, reach 5 ft. Hit: 4 (1d6 + 1) Bludgeoning damage.', 1),
  ('mud-mephit', 'Mud Breath (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 11, one creature the mephit can see within 15 feet. Failure: The target has the Restrained condition until the end of the mephit’s next turn.', 2),
  ('mumia', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The mummy makes two Rotting Fist attacks and uses Dreadful Glare.', 1),
  ('mumia', 'Rotting Fist', 'action'::rpg.actor_action_bucket, 5, '8', 'Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Bludgeoning damage plus 10 (3d6) Necrotic damage. If the target is a creature, it is cursed. While cursed, the target can’t regain Hit Points, its Hit Point maximum doesn’t return to normal when finishing a Long Rest, and its Hit Point maximum decreases by 10 (3d6) every 24 hours that elapse. A creature dies and turns to dust if reduced to 0 Hit Points by this attack.', 2),
  ('mumia', 'Dreadful Glare', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 11, one creature the mummy can see within 60 feet. Failure: The target has the Frightened condition until the end of the mummy’s next turn. Success: The target is immune to this mummy’s Dreadful Glare for 24 hours.', 3),
  ('mumia-lorde', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The mummy makes one Rotting Fist or Channel Negative Energy attack, and it uses Dreadful Glare.', 1),
  ('mumia-lorde', 'Rotting Fist', 'action'::rpg.actor_action_bucket, 9, '15', 'Melee Attack Roll: +9, reach 5 ft. Hit: 15 (2d10 + 4) Bludgeoning damage plus 10 (3d6) Necrotic damage. If the target is a creature, it is cursed. While cursed, the target can’t regain Hit Points, it gains no benefit from finishing a Long Rest, and its Hit Point maximum decreases by 10 (3d6) every 24 hours that elapse. A creature dies and turns to dust if reduced to 0 Hit Points by this attack.', 2),
  ('mumia-lorde', 'Channel Negative Energy', 'action'::rpg.actor_action_bucket, 9, '25', 'Ranged Attack Roll: +9, range 60 ft. Hit: 25 (6d6 + 4) Necrotic damage.', 3),
  ('mumia-lorde', 'Dreadful Glare', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 17, one creature the mummy can see within 60 feet. Failure: 25 (6d6 + 4) Psychic damage, and the target has the Paralyzed condition until the end of the mummy’s next turn.', 4),
  ('mumia-lorde', 'Spellcasting', 'action'::rpg.actor_action_bucket, 9, NULL, 'The mummy casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 17, +9 to hit with spell attacks):', 5),
  ('mumia-lorde', 'Whirlwind of Sand', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The mummy is hit by an attack roll. Response: The mummy adds 2 to its AC against the attack, possibly causing the attack to miss, and the mummy teleports up to 60 feet to an unoccupied space it can see. Each creature of its choice that it can see within 5 feet of its destination space has the Blinded condition until the end of the mummy’s next turn.', 6),
  ('mumia-lorde', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the mummy can expend a use to take one of the following actions. The mummy regains all expended uses at the start of each of its turns.', 7),
  ('mumia-lorde', 'Dread Command', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The mummy casts Command (level 2 version), using the same spellcasting ability as Spellcasting. The mummy can’t take this action again until the start of its next turn.', 8),
  ('mumia-lorde', 'Glare', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The mummy uses Dreadful Glare. The mummy can’t take this action again until the start of its next turn.', 9),
  ('mumia-lorde', 'Necrotic Strike', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The mummy makes one Rotting Fist or Channel Negative Energy attack.', 10),
