  ('naga-espiritual', 'Bite', 'action'::rpg.actor_action_bucket, 7, '7', 'Melee Attack Roll: +7, reach 10 ft. Hit: 7 (1d6 + 4) Piercing damage plus 14 (4d6) Poison damage.', 2),
  ('naga-espiritual', 'Necrotic Ray', 'action'::rpg.actor_action_bucket, 6, '21', 'Ranged Attack Roll: +6, range 60 ft. Hit: 21 (6d6) Necrotic damage.', 3),
