  ('nalfeshnee', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The nalfeshnee makes three Rend attacks.', 1),
  ('nalfeshnee', 'Rend', 'action'::rpg.actor_action_bucket, 10, '16', 'Melee Attack Roll: +10, reach 10 ft. Hit: 16 (2d10 + 5) Slashing damage plus 11 (2d10) Force damage.', 2),
  ('nalfeshnee', 'Teleport', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The nalfeshnee teleports up to 120 feet to an unoccupied space it can see.', 3),
  ('nalfeshnee', 'Horror Nimbus (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 15, each creature in a 15-foot Emanation originating from the nalfeshnee. Failure: 28 (8d6) Psychic damage, and the target has the Frightened condition for 1 minute, until it takes damage, or until it ends its turn with the nalfeshnee out of line of sight. Success: The target is immune to this nalfeshnee’s Horror Nimbus for 24 hours.', 4),
  ('nalfeshnee', 'Pursuit', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: Another creature the nalfeshnee can see ends its move within 120 feet of the nalfeshnee. Response: The nalfeshnee uses Teleport, but its destination space must be within 10 feet of the triggering creature.', 5),
  ('nicalote', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The nycaloth makes two Mercurial Axe attacks.', 1),
