  ('nicalote', 'Shadowy Teleport', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The nycaloth has the Invisible condition for 1 minute, and it teleports up to 30 feet to an unoccupied space it can see. The condition ends early immediately after it deals damage.', 3),
