  ('nobre', 'Parry', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The noble is hit by a melee attack roll while holding a weapon. Response: The noble adds 2 to its AC against that attack, possibly causing it to miss.', 2),
  ('nobre-prodigy', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The noble makes three Beguiling Strike attacks.', 1),
  ('nobre-prodigy', 'Beguiling Strike', 'action'::rpg.actor_action_bucket, 8, '18', 'Melee or Ranged Attack Roll: +8, reach 5 ft. or range 60 ft. Hit: 18 (4d6 + 4) Psychic damage, and the target has the Charmed condition until the start of the noble’s next turn.', 2),
  ('nobre-prodigy', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The noble casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 16):', 3),
  ('nobre-prodigy', 'Shield (2/Day)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The noble casts Shield in response to that spell’s trigger, using the same spellcasting ability as Spellcasting.', 4),
  ('noite-bruxa', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hag makes two Claw attacks.', 1),
