  ('noite-bruxa', 'Nightmare Haunting (1/Day; Requires Soul Bag)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'While on the Ethereal Plane, the hag casts Dream, using the same spellcasting ability as Spellcasting. Only the hag can serve as the spell’s messenger, and the target must be a creature the hag can see on the Material Plane. The spell fails and is wasted if the target is under the effect of the Protection from Evil and Good spell or within a Magic Circle spell.', 3),
  ('noite-bruxa', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hag casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save DC 14):', 4),
  ('noite-bruxa', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The hag shape-shifts into a Small or Medium Humanoid, or it returns to its true form. Other than its size, its game statistics are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 5),
  ('notico', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The nothic makes two Claw attacks.', 1),
