  ('notico', 'Rotting Gaze', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 13, one creature the nothic can see within 120 feet. Failure: 17 (5d6) Necrotic damage. Success: Half damage.', 3),
  ('notico', 'Weird Insight (Recharge 6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 14, one creature the nothic can see within 120 feet. Failure: The nothic magically learns one fact or secret about the target.', 4),
