  ('oni', 'Nightmare Ray', 'action'::rpg.actor_action_bucket, 5, '9', 'Ranged Attack Roll: +5, range 60 ft. Hit: 9 (2d6 + 2) Psychic damage, and the target has the Frightened condition until the start of the oni’s next turn.', 3),
  ('oni', 'Shape-Shift', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The oni shape-shifts into a Small or Medium Humanoid or a Large Giant, or it returns to its true form. Other than its size, its game statistics are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 4),
