  ('otyugh', 'Bite', 'action'::rpg.actor_action_bucket, 6, '12', 'Melee Attack Roll: +6, reach 5 ft. Hit: 12 (2d8 + 3) Piercing damage, and the target has the Poisoned condition. Whenever the Poisoned target finishes a Long Rest, it is subjected to the following effect. Constitution Saving Throw: DC 15. Failure: The target’s Hit Point maximum decreases by 5 (1d10) and doesn’t return to normal until the Poisoned condition ends on the target. Success: The Poisoned condition ends.', 2),
  ('otyugh', 'Tentacle', 'action'::rpg.actor_action_bucket, 6, '12', 'Melee Attack Roll: +6, reach 10 ft. Hit: 12 (2d8 + 3) Piercing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 13) from one of two tentacles.', 3),
  ('otyugh', 'Tentacle Slam', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 14, each creature Grappled by the otyugh. Failure: 16 (3d8 + 3) Bludgeoning damage, and the target has the Stunned condition until the start of the otyugh’s next turn. Success: Half damage only.', 4),
  ('pegaso', 'Hooves', 'action'::rpg.actor_action_bucket, 6, '7', 'Melee Attack Roll: +6, reach 5 ft. Hit: 7 (1d6 + 4) Bludgeoning damage plus 5 (2d4) Radiant damage.', 1),
