  ('performer', 'Uncanny Dodge', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The performer is hit by an attack roll. Response: The performer halves the damage (round down) it takes from that attack.', 2),
  ('performer-legend', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The performer makes three Bejeweled Baton attacks.', 1),
  ('performer-legend', 'Bejeweled Baton', 'action'::rpg.actor_action_bucket, 9, '10', 'Melee Attack Roll: +9, reach 5 ft. Hit: 10 (2d4 + 5) Bludgeoning damage plus 10 (3d6) Psychic damage.', 2),
  ('performer-legend', 'Majestic Song', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 17, each creature in a 20-foot-radius Sphere centered on a point within 120 feet. Failure: 22 (4d8 + 4) Psychic damage, and the target has the Charmed or Frightened condition (performer’s choice) until the end of the performer’s next turn. Success: Half damage only.', 3),
  ('performer-legend', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The performer casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 17):', 4),
  ('performer-legend', 'Warding Charm', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: A creature hits the performer with an attack roll. Response—Wisdom Saving Throw: DC 17, the triggering creature. Failure: The attack roll misses the performer, and the target has the Charmed condition until the end of the performer’s next turn.', 5),
