  ('performer-maestro', 'Beguiling Song', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 15, each creature in a 20-foot-radius Sphere centered on a point within 120 feet. Failure: 20 (3d10 + 4) Psychic damage, and the target has the Charmed condition until the end of the performer’s next turn. Success: Half damage only.', 3),
  ('performer-maestro', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The performer casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 15):', 4),
