  ('perfurador', 'Drop', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The piercer falls. Dexterity Saving Throw: DC 11, one creature directly underneath the piercer. Failure: 10 (3d6) Piercing damage. Failure or Success: The piercer reduces any damage it takes from the fall by 20.', 2),
  ('peritao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The peryton makes one Gore attack and one Talons attack.', 1),
  ('peritao', 'Gore', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage. If the peryton moved 30+ feet straight toward the target immediately before the hit, the target takes an extra 9 (2d8) Piercing damage.', 2),
