  ('pirate-admiral', 'Pistol', 'action'::rpg.actor_action_bucket, 10, '28', 'Ranged Attack Roll: +10, range 30/90 ft. Hit: 28 (4d10 + 6) Piercing damage.', 3),
  ('pirate-admiral', 'Rally (1/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The pirate chooses up to three other creatures it can see within 30 feet. Until the start of the pirate’s next turn, the targets have Advantage on attack rolls and saving throws.', 4),
  ('pirate-admiral', 'Defensive Stance', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The pirate is hit by a melee attack roll while holding a weapon. Response: The pirate adds 4 to its AC against melee attack rolls (including the triggering attack) until the start of its next turn, possibly causing the attacks to miss.', 5),
  ('pirate-captain', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The pirate makes three attacks, using Rapier or Pistol in any combination.', 1),
  ('pirate-captain', 'Rapier', 'action'::rpg.actor_action_bucket, 7, '13', 'Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Piercing damage, and the pirate has Advantage on the next attack roll it makes before the end of this turn.', 2),
  ('pirate-captain', 'Pistol', 'action'::rpg.actor_action_bucket, 7, '15', 'Ranged Attack Roll: +7, range 30/90 ft. Hit: 15 (2d10 + 4) Piercing damage.', 3),
  ('pirate-captain', 'Captain’s Charm', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 14, one creature the pirate can see within 30 feet. Failure: The target has the Charmed condition until the start of the pirate’s next turn.', 4),
  ('pirate-captain', 'Riposte', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The pirate is hit by a melee attack roll while holding a weapon. Response: The pirate adds 3 to its AC against that attack, possibly causing it to miss. On a miss, the pirate makes one Rapier attack against the triggering creature if within range.', 5),
  ('pit-fiend', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The pit fiend makes one Bite attack, two Devilish Claw attacks, and one Fiery Mace attack.', 1),
  ('pit-fiend', 'Bite', 'action'::rpg.actor_action_bucket, 14, '18', 'Melee Attack Roll: +14, reach 10 ft. Hit: 18 (3d6 + 8) Piercing damage. If the target is a creature, it must make the following saving throw. Constitution Saving Throw: DC 21. Failure: The target has the Poisoned condition. While Poisoned, the target can’t regain Hit Points and takes 21 (6d6) Poison damage at the start of each of its turns, and it repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.', 2),
  ('pit-fiend', 'Devilish Claw', 'action'::rpg.actor_action_bucket, 14, '26', 'Melee Attack Roll: +14, reach 10 ft. Hit: 26 (4d8 + 8) Necrotic damage.', 3),
  ('pit-fiend', 'Fiery Mace', 'action'::rpg.actor_action_bucket, 14, '22', 'Melee Attack Roll: +14, reach 10 ft. Hit: 22 (4d6 + 8) Force damage plus 21 (6d6) Fire damage.', 4),
  ('pit-fiend', 'Hellfire Spellcasting (Recharge 4–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The pit fiend casts Fireball (level 5 version) twice, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 21). It can replace one Fireball with Hold Monster (level 7 version) or Wall of Fire.', 5),
  ('pixie', 'Faerie Dust', 'action'::rpg.actor_action_bucket, 4, '1', 'Melee or Ranged Attack Roll: +4, reach 5 ft. or range 60 ft. Hit: 1 Radiant damage, and the target has the Charmed or Poisoned condition (pixie’s choice) until the start of the pixie’s next turn.', 1),
  ('pixie', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The pixie casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 12):', 2),
  ('pixie-wonderbringer', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The pixie makes two Faerie Dust attacks.', 1),
  ('pixie-wonderbringer', 'Faerie Dust', 'action'::rpg.actor_action_bucket, 7, '15', 'Melee or Ranged Attack Roll: +7, reach 5 ft. or range 60 ft. Hit: 15 (2d10 + 4) Radiant damage, and the target has the Charmed or Poisoned condition (pixie’s choice) until the start of the pixie’s next turn.', 2),
  ('pixie-wonderbringer', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The pixie casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 15):', 3),
  ('pixie-wonderbringer', 'Burst of Wonder (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The pixie casts Entangle, Polymorph, or Tasha’s Hideous Laughter, requiring no Material components and using the same spellcasting ability as Spellcasting.', 4),
  ('planetar', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The planetar makes three Radiant Sword attacks or uses Holy Burst twice.', 1),
  ('planetar', 'Radiant Sword', 'action'::rpg.actor_action_bucket, 12, '14', 'Melee Attack Roll: +12, reach 10 ft. Hit: 14 (2d6 + 7) Slashing damage plus 18 (4d8) Radiant damage.', 2),
  ('planetar', 'Holy Burst', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 20, each enemy in a 20-foot-radius Sphere centered on a point the planetar can see within 120 feet. Failure: 24 (7d6) Radiant damage. Success: Half damage.', 3),
  ('planetar', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The planetar casts one of the following spells, requiring no Material components and using Charisma as spellcasting ability (spell save DC 20):', 4),
  ('planetar', 'Divine Aid (2/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The planetar casts Cure Wounds, Invisibility, Lesser Restoration, or Remove Curse, using the same spellcasting ability as Spellcasting.', 5),
  ('poltergeist', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The poltergeist makes one Object Slam attack and uses Telekinetic Thrust.', 1),
  ('poltergeist', 'Object Slam', 'action'::rpg.actor_action_bucket, 4, '7', 'Melee or Ranged Attack Roll: +4, reach 5 ft. or range 30 ft. Hit: 7 (2d4 + 2) Bludgeoning damage.', 2),
  ('poltergeist', 'Telekinetic Thrust', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 12, one creature the poltergeist can see within 30 feet. Failure: 9 (2d6 + 2) Force damage, and the target is pushed up to 30 feet straight away from the poltergeist.', 3),
  ('poltergeist', 'Vanish', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The poltergeist gives itself the Invisible condition or ends that condition on itself.', 4),
  ('primeval-urso-coruja', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The owlbear makes two Ravage attacks.', 1),
  ('primeval-urso-coruja', 'Ravage', 'action'::rpg.actor_action_bucket, 9, '15', 'Melee Attack Roll: +9, reach 5 ft. Hit: 15 (2d8 + 6) Slashing damage. If the target is a Huge or smaller creature and the owlbear moved 20+ feet straight toward it immediately before the hit, the target takes an extra 9 (2d8) Slashing damage and has the Prone condition.', 2),
  ('primeval-urso-coruja', 'Screech (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 15, each creature in a 30-foot Emanation originating from the owlbear. Failure: 27 (6d8) Thunder damage, and the target has the Incapacitated condition until the end of its next turn. Success: Half damage only.', 3),
  ('prole-de-vampiro', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The vampire makes two Claw attacks and uses Bite.', 1),
  ('prole-de-vampiro', 'Claw', 'action'::rpg.actor_action_bucket, 6, '8', 'Melee Attack Roll: +6, reach 5 ft. Hit: 8 (2d4 + 3) Slashing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 13) from one of two claws.', 2),
  ('prole-de-vampiro', 'Bite', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 14, one creature within 5 feet that is willing or that has the Grappled, Incapacitated, or Restrained condition. Failure: 5 (1d4 + 3) Piercing damage plus 10 (3d6) Necrotic damage. The target’s Hit Point maximum decreases by an amount equal to the Necrotic damage taken, and the vampire regains Hit Points equal to that amount.', 3),
  ('prole-de-vampiro', 'Deathless Agility', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The vampire takes the Dash or Disengage action.', 4),
  ('pseudodragao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The pseudodragon makes two Bite attacks.', 1),
  ('pseudodragao', 'Bite', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Piercing damage.', 2),
  ('pseudodragao', 'Sting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 12, one creature the pseudodragon can see within 5 feet. Failure: 5 (2d4) Poison damage, and the target has the Poisoned condition for 1 hour. While Poisoned, the target also has the Unconscious condition, which ends early if the target takes damage or a creature within 5 feet of it takes an action to wake it.', 3),
  ('purpura-verme', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The worm makes one Bite attack and one Tail Stinger attack.', 1),
  ('purpura-verme', 'Bite', 'action'::rpg.actor_action_bucket, 14, '22', 'Melee Attack Roll: +14, reach 10 ft. Hit: 22 (3d8 + 9) Piercing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 19), and it has the Restrained condition until the grapple ends.', 2),
  ('purpura-verme', 'Tail Stinger', 'action'::rpg.actor_action_bucket, 14, '16', 'Melee Attack Roll: +14, reach 10 ft. Hit: 16 (2d6 + 9) Piercing damage plus 35 (10d6) Poison damage.', 3),
  ('purpura-verme', 'Swallow', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 19, one Large or smaller creature Grappled by the worm (it can have up to three creatures swallowed at a time). Failure: The target is swallowed by the worm, and the Grappled condition ends. A swallowed creature has the Blinded and Restrained conditions, has Total Cover against attacks and other effects outside the worm, and takes 17 (5d6) Acid damage at the start of each of the worm’s turns.', 4),
  ('quaggoth', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The quaggoth makes two Claw attacks.', 1),
  ('quaggoth', 'Claw', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Slashing damage, or 13 (3d6 + 3) Slashing damage if the quaggoth is Bloodied.', 2),
  ('quaggoth-thonot', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The quaggoth makes two Claw attacks.', 1),
  ('quaggoth-thonot', 'Claw', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Slashing damage plus 5 (2d4) Psychic damage.', 2),
  ('quaggoth-thonot', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The quaggoth casts one of the following spells, requiring no spell components and using Wisdom as the spellcasting ability (spell save DC 12):', 3),
  ('quaggoth-thonot', 'Psionic Defense (3/Day)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The quaggoth casts Feather Fall or Shield in response to the spell’s trigger, requiring no spell components and using the same spellcasting ability as Spellcasting.', 4),
  ('quasit', 'Rend', 'action'::rpg.actor_action_bucket, 5, '5', 'Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Slashing damage, and the target has the Poisoned condition until the start of the quasit’s next turn.', 1),
  ('quasit', 'Invisibility', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The quasit casts Invisibility on itself, requiring no spell components and using Charisma as the spellcasting ability.', 2),
  ('quasit', 'Scare (1/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 10, one creature within 20 feet. Failure: The target has the Frightened condition. At the end of each of its turns, the target repeats the save, ending the effect on itself on a success. After 1 minute, it succeeds automatically.', 3),
  ('quasit', 'Shape-Shift', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The quasit shape-shifts to resemble a bat (Speed 10 ft., Fly 40 ft.), a centipede (40 ft., Climb 40 ft.), or a toad (40 ft., Swim 40 ft.), or it returns to its true form. Its game statistics are the same in each form, except for its Speed. Any equipment it is wearing or carrying isn’t transformed.', 4),
  ('rakshasa', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The rakshasa makes three Cursed Touch attacks.', 1),
  ('rakshasa', 'Cursed Touch', 'action'::rpg.actor_action_bucket, 10, '12', 'Melee Attack Roll: +10, reach 5 ft. Hit: 12 (2d6 + 5) Slashing damage plus 19 (3d12) Necrotic damage. If the target is a creature, it is cursed. While cursed, the target gains no benefit from finishing a Short or Long Rest.', 2),
  ('rakshasa', 'Baleful Command (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 18, each enemy in a 30-foot Emanation originating from the rakshasa. Failure: 28 (8d6) Psychic damage, and the target has the Frightened and Incapacitated conditions until the start of the rakshasa’s next turn.', 3),
  ('rakshasa', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The rakshasa casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 18):', 4),
  ('rato-homem', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The wererat makes two attacks, using Scratch or Hand Crossbow in any combination. It can replace one attack with a Bite attack.', 1),
  ('rato-homem', 'Bite (Rat or Hybrid Form Only)', 'action'::rpg.actor_action_bucket, 5, '8', 'Melee Attack Roll: +5, reach 5 ft. Hit: 8 (2d4 + 3) Piercing damage. If the target is a Humanoid, it is subjected to the following effect. Constitution Saving Throw: DC 11. Failure: The target is cursed. If the cursed target drops to 0 Hit Points, it instead becomes a Wererat under the DM’s control and has 10 Hit Points. Success: The target is immune to this wererat’s curse for 24 hours.', 2),
  ('rato-homem', 'Scratch', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Slashing damage.', 3),
  ('rato-homem', 'Hand Crossbow (Humanoid or Hybrid Form Only)', 'action'::rpg.actor_action_bucket, 5, '6', 'Ranged Attack Roll: +5, range 30/120 ft. Hit: 6 (1d6 + 3) Piercing damage.', 4),
  ('rato-homem', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The wererat shape-shifts into a Medium rat-humanoid hybrid or a Small rat, or it returns to its true humanoid form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 5),
  ('remorhaz', 'Bite', 'action'::rpg.actor_action_bucket, 11, '18', 'Melee Attack Roll: +11, reach 10 ft. Hit: 18 (2d10 + 7) Piercing damage plus 14 (4d6) Fire damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 17), and it has the Restrained condition until the grapple ends.', 1),
  ('remorhaz', 'Swallow', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 19, one Large or smaller creature Grappled by the remorhaz (it can have up to two creatures swallowed at a time). Failure: The target is swallowed by the remorhaz, and the Grappled condition ends. A swallowed creature has the Blinded and Restrained conditions, it has Total Cover against attacks and other effects outside the remorhaz, and it takes 10 (3d6) Acid damage plus 10 (3d6) Fire damage at the start of each of the remorhaz’s turns.', 2),
  ('revenante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The revenant uses Vengeful Glare and makes two Slam attacks.', 1),
  ('revenante', 'Slam', 'action'::rpg.actor_action_bucket, 7, '11', 'Melee Attack Roll: +7, reach 5 ft. Hit: 11 (2d6 + 4) Necrotic damage.', 2),
  ('revenante', 'Vengeful Glare', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 15, one creature the revenant can see within 30 feet. Failure: The target has the Frightened condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically. If the Frightened target is cursed by the revenant (see Vow of Revenge), the target also has the Paralyzed condition for the duration.', 3),
  ('revenante', 'Vow of Revenge (1/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The revenant curses one creature it can see within 30 feet of itself. The revenant knows the distance to and direction of the cursed target, even if it is on a different plane of existence. The curse ends on the target if the revenant uses this Bonus Action on a different creature.', 4),
  ('roc', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The roc makes two Beak attacks. It can replace one attack with a Talons attack.', 1),
  ('roc', 'Beak', 'action'::rpg.actor_action_bucket, 13, '28', 'Melee Attack Roll: +13, reach 10 ft. Hit: 28 (3d12 + 9) Piercing damage.', 2),
  ('roc', 'Talons', 'action'::rpg.actor_action_bucket, 13, '23', 'Melee Attack Roll: +13, reach 5 ft. Hit: 23 (4d6 + 9) Slashing damage. If the target is a Huge or smaller creature, it has the Grappled condition (escape DC 19) from both talons, and it has the Restrained condition until the grapple ends.', 3),
  ('roc', 'Swoop (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'If the roc has a creature Grappled, the roc flies up to half its Fly Speed without provoking Opportunity Attacks and drops that creature.', 4),
  ('roper', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The roper makes two Tentacle attacks, uses Reel, and makes two Bite attacks.', 1),
  ('roper', 'Bite', 'action'::rpg.actor_action_bucket, 7, '17', 'Melee Attack Roll: +7, reach 5 ft. Hit: 17 (3d8 + 4) Piercing damage.', 2),
  ('roper', 'Tentacle', 'action'::rpg.actor_action_bucket, 7, NULL, 'Melee Attack Roll: +7, reach 60 ft. Hit: The target has the Grappled condition (escape DC 14) from one of six tentacles, and the target has the Poisoned condition until the grapple ends.', 3),
  ('roper', 'Reel', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The roper pulls each creature Grappled by it up to 30 feet straight toward it.', 4),
