  ('sahuagin-barao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The sahuagin makes three Trident attacks.', 1),
  ('sahuagin-barao', 'Trident', 'action'::rpg.actor_action_bucket, 7, '13', 'Melee or Ranged Attack Roll: +7, reach 5 ft. or range 20/60 ft. Hit: 13 (2d8 + 4) Piercing damage.', 2),
  ('sahuagin-barao', 'Fiendish Blood', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The sahuagin takes Piercing or Slashing damage. Response—Constitution Saving Throw: DC 14, each creature of the sahuagin’s choice in a 5-foot Emanation originating from the sahuagin. Failure: 10 (3d6) Acid damage, and the target is cursed until it finishes a Short or Long Rest. While cursed, the target can’t benefit from the Invisible condition, its Speed decreases by 10 feet, and all Fiends within 120 feet of the target can sense its location regardless of interposing obstacles.', 3),
