  ('sahuagin-guerreiro', 'Aquatic Charge', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The sahuagin swims up to its Swim Speed straight toward an enemy it can see.', 3),
  ('sahuagin-sacerdote', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The sahuagin makes two Spectral Jaws attacks.', 1),
  ('sahuagin-sacerdote', 'Spectral Jaws', 'action'::rpg.actor_action_bucket, 4, '11', 'Melee or Ranged Attack Roll: +4, reach 5 ft. or range 120 ft. Hit: 11 (2d8 + 2) Force damage.', 2),
  ('sahuagin-sacerdote', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The sahuagin casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 12):', 3),
