  ('salamandra', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The salamander makes two Flame Spear attacks. It can replace one attack with a use of Constrict.', 1),
  ('salamandra', 'Flame Spear', 'action'::rpg.actor_action_bucket, 7, '13', 'Melee or Ranged Attack Roll: +7, reach 5 ft. or range 20/60 ft. Hit: 13 (2d8 + 4) Piercing damage plus 7 (2d6) Fire damage. Hit or Miss: The spear magically returns to the salamander’s hand immediately after a ranged attack.', 2),
  ('salamandra', 'Constrict', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 15, one Large or smaller creature the salamander can see within 10 feet. Failure: 11 (2d6 + 4) Bludgeoning damage plus 7 (2d6) Fire damage. The target has the Grappled condition (escape DC 14), and it has the Restrained condition until the grapple ends.', 3),
  ('salamandra-cobra-de-fogo', 'Bite', 'action'::rpg.actor_action_bucket, 4, '6', 'Melee Attack Roll: +4, reach 5 ft. Hit: 6 (1d8 + 2) Piercing damage plus 3 (1d6) Fire damage.', 1),
  ('salamandra-mestre-do-inferno', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The salamander makes two Flame Trident attacks.', 1),
  ('salamandra-mestre-do-inferno', 'Flame Trident', 'action'::rpg.actor_action_bucket, 12, '16', 'Melee or Ranged Attack Roll: +12, reach 5 ft. or range 30/90 ft. Hit: 16 (2d8 + 7) Piercing damage plus 14 (4d6) Fire damage. Hit or Miss: The trident magically returns to the salamander’s hand immediately after a ranged attack.', 2),
  ('salamandra-mestre-do-inferno', 'Inferno Blast (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 18, each creature in a 30-foot-radius Sphere centered on a point the salamander can see within 120 feet. Failure: 35 (10d6) Fire damage, and the target starts burning, taking 5 (1d10) Fire damage at the start of each of its turns instead of the normal burning damage. The target gains 1 Exhaustion level whenever it takes this burning damage. Success: Half damage only.', 3),
  ('salamandra-mestre-do-inferno', 'Blazing Movement', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The salamander moves up to its Speed without provoking Opportunity Attacks. During this movement, fire fills a 5-foot Emanation originating from the salamander. When the Emanation enters a creature’s space, that creature takes 7 (2d6) Fire damage. A creature can take this damage only once per turn.', 4),
  ('satir-mestre-da-festa', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The satyr makes three Prance attacks.', 1),
  ('satir-mestre-da-festa', 'Prance', 'action'::rpg.actor_action_bucket, 7, '13', 'Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Bludgeoning damage, and the target has the Charmed condition until the start of the satyr’s next turn.', 2),
  ('satir-mestre-da-festa', 'Fey Melody (Recharge 4–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The satyr conjures a charming or frightening song. Wisdom Saving Throw: DC 14, each enemy in a 60-foot Emanation originating from the satyr. Failure: The target is subjected to the song’s effect:', 3),
  ('satiro', 'Hooves', 'action'::rpg.actor_action_bucket, 5, '5', 'Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Bludgeoning damage. If the target is a Medium or smaller creature, the satyr pushes the target up to 10 feet straight away from itself.', 1),
  ('satiro', 'Mockery', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 12, one creature the satyr can see within 90 feet. Failure: 5 (1d6 + 2) Psychic damage.', 2),
  ('slaad-azul', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The slaad makes three Mutating Claw attacks.', 1),
  ('slaad-azul', 'Mutating Claw', 'action'::rpg.actor_action_bucket, 8, '12', 'Melee Attack Roll: +8, reach 10 ft. Hit: 12 (2d6 + 5) Slashing damage plus 3 (1d6) Poison damage. If the target is a Humanoid not cursed by a slaad, it is subjected to the following effect. Constitution Saving Throw: DC 15. Failure: The target is cursed. The cursed target can’t regain Hit Points, and its Hit Point maximum decreases by 10 (3d6) after every 24 hours and doesn’t return to normal after finishing a Long Rest. If the curse reduces the target’s Hit Point maximum to 0, the curse ends, and instead of dying, the target instantly transforms into a Red Slaad or, if it can cast spells of level 3 or higher, a Green Slaad. Only a Wish spell can reverse this transformation.', 2),
  ('slaad-cinzento', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The slaad makes two Chaos Claw attacks.', 1),
  ('slaad-cinzento', 'Chaos Claw', 'action'::rpg.actor_action_bucket, 8, '9', 'Melee Attack Roll: +8, reach 10 ft. Hit: 9 (1d10 + 4) Slashing damage plus 11 (2d10) Necrotic damage. Until the start of the slaad’s next turn, the target has a condition determined by rolling 1d4: on a 1, Charmed; on a 2, Frightened; on a 3, Poisoned; or on a 4, Incapacitated.', 2),
  ('slaad-cinzento', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The slaad casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 16):', 3),
  ('slaad-cinzento', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The slaad shape-shifts into a Small or Medium Humanoid, or it returns to its true form. Other than its size, its game statistics are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 4),
  ('slaad-da-morte', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The slaad makes two Chaos Blade attacks.', 1),
  ('slaad-da-morte', 'Chaos Blade', 'action'::rpg.actor_action_bucket, 9, '11', 'Melee Attack Roll: +9, reach 10 ft. Hit: 11 (1d12 + 5) Slashing damage plus 10 (3d6) Necrotic damage. Until the start of the slaad’s next turn, the target has a condition determined by rolling 1d4: on a 1, Charmed; on a 2, Frightened; on a 3, Poisoned; or on a 4, Incapacitated.', 2),
  ('slaad-da-morte', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The slaad casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 16):', 3),
  ('slaad-da-morte', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The slaad shape-shifts into a Small or Medium Humanoid, or it returns to its true form. Other than its size, its game statistics are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 4),
  ('slaad-girino', 'Bite', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage.', 1),
  ('slaad-verde', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The slaad makes three Chaos Staff attacks.', 1),
  ('slaad-verde', 'Chaos Staff', 'action'::rpg.actor_action_bucket, 7, '8', 'Melee or Ranged Attack Roll: +7, reach 10 ft. or range 60 ft. Hit: 8 (1d8 + 4) Force damage. Until the start of the slaad’s next turn, the target has a condition determined by rolling 1d4: on a 1, Charmed; on a 2, Frightened; on a 3, Poisoned; or on a 4, Incapacitated.', 2),
  ('slaad-verde', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The slaad casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 14):', 3),
  ('slaad-verde', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The slaad shape-shifts into a Small or Medium Humanoid, or it returns to its true form. Other than its size, its game statistics are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 4),
  ('slaad-vermelho', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The slaad makes three Injecting Claw attacks.', 1),
  ('slaad-vermelho', 'Injecting Claw', 'action'::rpg.actor_action_bucket, 6, '10', 'Melee Attack Roll: +6, reach 10 ft. Hit: 10 (2d6 + 3) Piercing damage. If the target is a Humanoid not cursed by a slaad, it is subjected to the following effect. Constitution Saving Throw: DC 14. Failure: The target is cursed unawares, and a minuscule slaad egg is implanted in it. Removing the curse destroys the egg.', 2),
  ('smoke-mephit', 'Claw', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Slashing damage.', 1),
  ('smoke-mephit', 'Cinder Breath (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 11, one creature the mephit can see within 15 feet. Failure: The target has the Blinded condition until the end of the mephit’s next turn.', 2),
  ('solar', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The solar makes two Flying Sword attacks. It can replace one attack with a use of Slaying Bow.', 1),
  ('solar', 'Flying Sword', 'action'::rpg.actor_action_bucket, 15, '22', 'Melee or Ranged Attack Roll: +15, reach 10 ft. or range 120 ft. Hit: 22 (4d6 + 8) Slashing damage plus 36 (8d8) Radiant damage. Hit or Miss: The sword magically returns to the solar’s hand or hovers within 5 feet of the solar immediately after a ranged attack.', 2),
  ('solar', 'Slaying Bow', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 21, one creature the solar can see within 600 feet. Failure: If the creature has 100 Hit Points or fewer, it dies. It otherwise takes 24 (4d8 + 6) Piercing damage plus 36 (8d8) Radiant damage.', 3),
  ('solar', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The solar casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 25):', 4),
  ('solar', 'Divine Aid (3/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The solar casts Cure Wounds (level 2 version), Lesser Restoration, or Remove Curse, using the same spellcasting ability as Spellcasting.', 5),
  ('solar', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3. Immediately after another creature’s turn, the solar can expend a use to take one of the following actions. The solar regains all expended uses at the start of each of its turns.', 6),
  ('solar', 'Blinding Gaze', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 25, one creature the solar can see within 120 feet. Failure: The target has the Blinded condition for 1 minute. Failure or Success: The solar can’t take this action again until the start of its next turn.', 7),
  ('solar', 'Radiant Teleport', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The solar teleports up to 60 feet to an unoccupied space it can see. Dexterity Saving Throw: DC 25, each creature in a 10-foot Emanation originating from the solar at its destination space. Failure: 11 (2d10) Radiant damage. Success: Half damage.', 8),
  ('sombra', 'Draining Swipe', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Necrotic damage, and the target’s Strength score decreases by 1d4. The target dies if this reduces that score to 0. If a Humanoid is slain by this attack, a Shadow rises from the corpse 1d4 hours later.', 1),
  ('sombra', 'Shadow Stealth', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'While in Dim Light or Darkness, the shadow takes the Hide action.', 2),
  ('sprite', 'Needle Sword', 'action'::rpg.actor_action_bucket, 6, '6', 'Melee Attack Roll: +6, reach 5 ft. Hit: 6 (1d4 + 4) Piercing damage.', 1),
  ('sprite', 'Enchanting Bow', 'action'::rpg.actor_action_bucket, 6, '1', 'Ranged Attack Roll: +6, range 40/160 ft. Hit: 1 Piercing damage, and the target has the Charmed condition until the start of the sprite’s next turn.', 2),
  ('sprite', 'Heart Sight', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Charisma Saving Throw: DC 10, one creature within 5 feet the sprite can see (Celestials, Fiends, and Undead automatically fail the save). Failure: The sprite knows the target’s emotions and alignment.', 3),
  ('sprite', 'Invisibility', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The sprite casts Invisibility on itself, requiring no spell components and using Charisma as the spellcasting ability.', 4),
  ('steam-mephit', 'Claw', 'action'::rpg.actor_action_bucket, 2, '2', 'Melee Attack Roll: +2, reach 5 ft. Hit: 2 (1d4) Slashing damage plus 2 (1d4) Fire damage.', 1),
  ('steam-mephit', 'Steam Breath (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 10, each creature in a 15-foot Cone. Failure: 5 (2d4) Fire damage, and the target’s Speed decreases by 10 feet until the end of the mephit’s next turn. Success: Half damage only. Failure or Success: Being underwater doesn’t grant Resistance to this Fire damage.', 2),
  ('stirge', 'Proboscis', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage, and the stirge attaches to the target. While attached, the stirge can’t make Proboscis attacks, and the target takes 5 (2d4) Necrotic damage at the start of each of the stirge’s turns.', 1),
  ('sucubo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The succubus makes one Fiendish Touch attack and uses Charm or Draining Kiss.', 1),
  ('sucubo', 'Fiendish Touch', 'action'::rpg.actor_action_bucket, 7, '16', 'Melee Attack Roll: +7, reach 5 ft. Hit: 16 (2d10 + 5) Psychic damage.', 2),
  ('sucubo', 'Charm', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The succubus casts Dominate Person (level 8 version), requiring no spell components and using Charisma as the spellcasting ability (spell save DC 15).', 3),
  ('sucubo', 'Draining Kiss', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 15, one creature Charmed by the succubus within 5 feet. Failure: 13 (3d8) Psychic damage. Success: Half damage. Failure or Success: The target’s Hit Point maximum decreases by an amount equal to the damage taken.', 4),
  ('sucubo', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The succubus shape-shifts into a Medium or Small Humanoid, or it returns to its true form. Its game statistics are the same in each form, except its Fly Speed is available only in its true form. Any equipment it is wearing or carrying isn’t transformed.', 5),
  ('tarrasque', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The tarrasque makes one Bite attack and three other attacks, using Claw or Tail in any combination.', 1),
  ('tarrasque', 'Bite', 'action'::rpg.actor_action_bucket, 19, '36', 'Melee Attack Roll: +19, reach 15 ft. Hit: 36 (4d12 + 10) Piercing damage, and the target has the Grappled condition (escape DC 20). Until the grapple ends, the target has the Restrained condition and can’t teleport.', 2),
  ('tarrasque', 'Claw', 'action'::rpg.actor_action_bucket, 19, '28', 'Melee Attack Roll: +19, reach 15 ft. Hit: 28 (4d8 + 10) Slashing damage.', 3),
  ('tarrasque', 'Tail', 'action'::rpg.actor_action_bucket, 19, '23', 'Melee Attack Roll: +19, reach 30 ft. Hit: 23 (3d8 + 10) Bludgeoning damage. If the target is a Huge or smaller creature, it has the Prone condition.', 4),
  ('tarrasque', 'Thunderous Bellow (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 27, each creature and each object that isn’t being worn or carried in a 150-foot Cone. Failure: 78 (12d12) Thunder damage, and the target has the Deafened and Frightened conditions until the end of its next turn. Success: Half damage only.', 5),
  ('tarrasque', 'Swallow', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 27, one Large or smaller creature Grappled by the tarrasque (it can have up to six creatures swallowed at a time). Failure: The target is swallowed, and the Grappled condition ends. A swallowed creature has the Blinded and Restrained conditions and can’t teleport, it has Total Cover against attacks and other effects outside the tarrasque, and it takes 56 (16d6) Acid damage at the start of each of the tarrasque’s turns.', 6),
  ('tarrasque', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3. Immediately after another creature’s turn, the tarrasque can expend a use to take one of the following actions. The tarrasque regains all expended uses at the start of each of its turns.', 7),
  ('tarrasque', 'Onslaught', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The tarrasque moves up to half its Speed, and it makes one Claw or Tail attack.', 8),
  ('tarrasque', 'World-Shaking Movement', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The tarrasque moves up to its Speed. At the end of this movement, the tarrasque creates an instantaneous shock wave in a 60-foot Emanation originating from itself. Creatures in that area lose Concentration and, if Medium or smaller, have the Prone condition. The tarrasque can’t take this action again until the start of its next turn.', 9),
  ('thri-kreen-psion', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The thri-kreen makes three Psionic Lance attacks.', 1),
  ('thri-kreen-psion', 'Psionic Lance', 'action'::rpg.actor_action_bucket, 7, '18', 'Melee or Ranged Attack Roll: +7, reach 10 ft. or range 120 ft. Hit: 18 (4d6 + 4) Psychic damage.', 2),
  ('thri-kreen-psion', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The thri-kreen casts one of the following spells, requiring no spell components and using Intelligence as the spellcasting ability (spell save DC 15):', 3),
  ('thri-kreen-saqueador', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The thri-kreen makes two attacks, using Gythka or Chatkcha in any combination.', 1),
  ('thri-kreen-saqueador', 'Gythka', 'action'::rpg.actor_action_bucket, 3, '5', 'Melee Attack Roll: +3, reach 5 ft. Hit: 5 (1d8 + 1) Slashing damage plus 2 (1d4) Poison damage.', 2),
  ('thri-kreen-saqueador', 'Chatkcha', 'action'::rpg.actor_action_bucket, 4, '5', 'Ranged Attack Roll: +4, range 30/120 ft. Hit: 5 (1d6 + 2) Slashing damage.', 3),
  ('thri-kreen-saqueador', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The thri-kreen jumps up to 15 feet by spending 5 feet of movement.', 4),
  ('tigre-homem', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The weretiger makes two attacks, using Scratch or Longbow in any combination. It can replace one attack with a Bite attack.', 1),
  ('tigre-homem', 'Bite (Tiger or Hybrid Form Only)', 'action'::rpg.actor_action_bucket, 5, '12', 'Melee Attack Roll: +5, reach 5 ft. Hit: 12 (2d8 + 3) Piercing damage. If the target is a Humanoid, it is subjected to the following effect. Constitution Saving Throw: DC 13. Failure: The target is cursed. If the cursed target drops to 0 Hit Points, it instead becomes a Weretiger under the DM’s control and has 10 Hit Points. Success: The target is immune to this weretiger’s curse for 24 hours.', 2),
  ('tigre-homem', 'Scratch', 'action'::rpg.actor_action_bucket, 5, '10', 'Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage.', 3),
  ('tigre-homem', 'Longbow (Humanoid or Hybrid Form Only)', 'action'::rpg.actor_action_bucket, 4, '11', 'Ranged Attack Roll: +4, range 150/600 ft. Hit: 11 (2d8 + 2) Piercing damage.', 4),
  ('tigre-homem', 'Prowl (Tiger or Hybrid Form Only)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The weretiger moves up to its Speed without provoking Opportunity Attacks. At the end of this movement, the weretiger can take the Hide action.', 5),
  ('tigre-homem', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The weretiger shape-shifts into a Large tiger-humanoid hybrid or a Large tiger, or it returns to its true humanoid form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 6),
  ('tritao-skirmisher', 'Ocean Spear', 'action'::rpg.actor_action_bucket, 2, '3', 'Melee or Ranged Attack Roll: +2, reach 5 ft. or range 20/60 ft. Hit: 3 (1d6) Piercing damage plus 2 (1d4) Cold damage. If the target is a creature, its Speed decreases by 10 feet until the end of its next turn. Hit or Miss: The spear magically returns to the merfolk’s hand immediately after a ranged attack.', 1),
  ('tritao-wavebender', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The merfolk makes two Aquatic Burst attacks.', 1),
  ('tritao-wavebender', 'Aquatic Burst', 'action'::rpg.actor_action_bucket, 7, '20', 'Melee or Ranged Attack Roll: +7, reach 5 ft. or range 60 ft. Hit: 20 (3d10 + 4) Cold damage. If the target is a Large or smaller creature, it has the Prone condition.', 2),
  ('tritao-wavebender', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The merfolk casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 15):', 3),
  ('tritao-wavebender', 'Watery Rebuke', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: An enemy the merfolk can see enters a space within 5 feet of the merfolk. Response—Strength Saving Throw: DC 15, the triggering enemy. Failure: 14 (4d6) Cold damage. If the target is Large or smaller, it is pushed up to 30 feet straight away from the merfolk by conjured water.', 4),
  ('troglodita', 'Rend', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Slashing damage.', 1),
  ('troll', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The troll makes three Rend attacks.', 1),
  ('troll', 'Rend', 'action'::rpg.actor_action_bucket, 7, '11', 'Melee Attack Roll: +7, reach 10 ft. Hit: 11 (2d6 + 4) Slashing damage.', 2),
  ('troll', 'Charge', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The troll moves up to half its Speed straight toward an enemy it can see.', 3),
  ('ultrolote', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ultroloth uses Hypnotic Gaze and makes two Mercurial Whip attacks.', 1),
  ('ultrolote', 'Mercurial Whip', 'action'::rpg.actor_action_bucket, 9, '25', 'Melee Attack Roll: +9, reach 15 ft. Hit: 25 (6d6 + 4) Force damage, and the ultroloth can teleport the target up to 10 feet to an unoccupied space the ultroloth can see that isn’t in the air.', 2),
  ('ultrolote', 'Hypnotic Gaze', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 17, each creature in a 30-foot Cone. Failure: 10 (3d6) Psychic damage, and the target has the Stunned condition until the start of the ultroloth’s next turn. Success: The target is immune to this ultroloth’s Hypnotic Gaze for 24 hours.', 3),
  ('ultrolote', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ultroloth casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save DC 17):', 4),
  ('ultrolote', 'Fiendish Guile (Recharge 4–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The ultroloth casts Dispel Magic, Invisibility (self only), Misty Step, or Suggestion, requiring no Material components and using the same spellcasting ability as Spellcasting.', 5),
  ('umber-hulk', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The umber hulk makes three Rend attacks.', 1),
  ('umber-hulk', 'Rend', 'action'::rpg.actor_action_bucket, 8, '12', 'Melee Attack Roll: +8, reach 10 ft. Hit: 12 (2d6 + 5) Slashing damage.', 2),
  ('umber-hulk', 'Confusing Gaze (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 14, each creature in a 30-foot Cone. Failure: The target can’t take Reactions until the start of the umber hulk’s next turn, and the target rolls 1d8 to determine what it does on its next turn:', 3),
  ('unicornio', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The unicorn makes one Hooves attack and one Radiant Horn attack.', 1),
