  ('unicornio', 'Radiant Horn', 'action'::rpg.actor_action_bucket, 7, '9', 'Melee Attack Roll: +7, reach 5 ft. Hit: 9 (1d10 + 4) Radiant damage.', 3),
  ('unicornio', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The unicorn casts one of the following spells, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 14):', 4),
  ('unicornio', 'Unicorn’s Blessing (3/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The unicorn touches another creature with its horn and casts Cure Wounds or Lesser Restoration on that creature, using the same spellcasting ability as Spellcasting.', 5),
  ('unicornio', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3. Immediately after another creature’s turn, the unicorn can expend a use to take one of the following actions. The unicorn regains all expended uses at the start of each of its turns.', 6),
  ('unicornio', 'Charging Horn', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The unicorn moves up to half its Speed without provoking Opportunity Attacks, and it makes one Radiant Horn attack.', 7),
  ('unicornio', 'Shimmering Shield', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The unicorn targets itself or one creature it can see within 60 feet of itself. The target gains 10 (3d6) Temporary Hit Points, and its AC increases by 2 until the end of the unicorn’s next turn. The unicorn can’t take this action again until the start of its next turn.', 8),
  ('urso-coruja', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The owlbear makes two Rend attacks.', 1),
